import { Archive, CircleAlert, Eye, FileText, KeyRound, ListFilter, PackageOpen, Plus, RefreshCw, RotateCcw, Trash2, Upload } from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { api, type HostsManagerGroup, type HostsManagerHost, type ModuleStatus, type OsRepository, type OsRepositoryAssignment, type OsRepositoryChannel, type OsRepositoryDashboard, type OsRepositoryJob, type OsRepositoryKey, type OsRepositoryPackage, type OsRepositorySnapshot } from "../../../api";
import type { ToastFn, Translate } from "../../../app/types";
import { Modal } from "../../../components/Modal";
import { useRefreshOnConnectionRestored } from "../../connection/ConnectionStatusMonitor";
import { ModuleAppShell, type ModuleSection } from "../common/ModuleAppShell";

const sections: ModuleSection[] = ["overview", "repositories", "packages", "synchronizations", "snapshots", "channels", "builder", "keys", "assignments", "jobs", "history", "settings"];
const fallbackStatus: ModuleStatus = { installed: true, package_version: "1.0.0", update_available: false, service_state: "unknown", service_enabled: false, services: {}, health: "unknown", health_message: "", last_action: "", last_action_status: "", last_error: "", metrics: {} };

function bytes(value: number): string {
  if (!value) return "0 B";
  const units = ["B", "KiB", "MiB", "GiB", "TiB"];
  const index = Math.min(Math.floor(Math.log(value) / Math.log(1024)), units.length - 1);
  return `${(value / 1024 ** index).toFixed(index ? 1 : 0)} ${units[index]}`;
}

export function OsRepositoriesApp({ permissions, t, toast }: { permissions: string[]; t: Translate; toast: ToastFn }) {
  const [section, setSection] = useState<ModuleSection>("overview");
  const [status, setStatus] = useState(fallbackStatus);
  const [dashboard, setDashboard] = useState<OsRepositoryDashboard | null>(null);
  const [repositories, setRepositories] = useState<OsRepository[]>([]);
  const [packages, setPackages] = useState<OsRepositoryPackage[]>([]);
  const [snapshots, setSnapshots] = useState<OsRepositorySnapshot[]>([]);
  const [channels, setChannels] = useState<OsRepositoryChannel[]>([]);
  const [jobs, setJobs] = useState<OsRepositoryJob[]>([]);
  const [keys, setKeys] = useState<OsRepositoryKey[]>([]);
  const [assignments, setAssignments] = useState<OsRepositoryAssignment[]>([]);
  const [history, setHistory] = useState<Array<{ id: number; actor: string; action: string; target: string; created_at: number }>>([]);
  const [settings, setSettings] = useState({ listen_address: "0.0.0.0", port: 8088, public_base_url: "", upload_limit_mb: 2048, max_parallel_syncs: 1 });
  const [search, setSearch] = useState("");
  const [loading, setLoading] = useState(true);
  const [repositoryDialog, setRepositoryDialog] = useState<OsRepository | null | undefined>(undefined);
  const [filterRepository, setFilterRepository] = useState<OsRepository | null>(null);
  const [buildOpen, setBuildOpen] = useState(false);
  const [uploadOpen, setUploadOpen] = useState(false);
  const [snapshotOpen, setSnapshotOpen] = useState(false);
  const [keyOpen, setKeyOpen] = useState(false);
  const [assignmentOpen, setAssignmentOpen] = useState(false);
  const [jobOpen, setJobOpen] = useState<string | null>(null);
  const [packageOpen, setPackageOpen] = useState<OsRepositoryPackage | null>(null);
  const [configuration, setConfiguration] = useState<{ filename: string; content: string; public_key_url: string } | null>(null);
  const canManage = permissions.includes("os-repositories.manage");
  const canSync = permissions.includes("os-repositories.sync");
  const canViewKeys = permissions.includes("os-repositories.keys.view");
  const visibleSections = canViewKeys ? sections : sections.filter((item) => item !== "keys");

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const results = await Promise.all([api.module("os-repositories"), api.osRepositoriesDashboard(), api.osRepositories(search), api.osRepositoryPackages(search), api.osRepositorySnapshots(), api.osRepositoryChannels(), api.osRepositoryJobs(), canViewKeys ? api.osRepositoryKeys() : Promise.resolve([]), api.osRepositoryAssignments(), api.osRepositoryHistory(), api.osRepositorySettings()]);
      setStatus(results[0].module_status); setDashboard(results[1]); setRepositories(results[2].items); setPackages(results[3].items); setSnapshots(results[4].items); setChannels(results[5]); setJobs(results[6].items); setKeys(results[7]); setAssignments(results[8]); setHistory(results[9]); setSettings(results[10]);
    } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error", "admin", "os-repositories"); }
    finally { setLoading(false); }
  }, [canViewKeys, search, t, toast]);
  useEffect(() => { void refresh(); }, [refresh]);
  useRefreshOnConnectionRestored(() => { void refresh(); });
  const activeJob = jobs.find((job) => ["queued", "running"].includes(job.status));

  async function sync(repository: OsRepository) {
    try { await api.syncOsRepository(repository.id); toast(t("osRepositories.syncQueued"), "ok", "admin", "os-repositories"); await refresh(); }
    catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error", "admin", "os-repositories"); }
  }
  const filteredRepositories = useMemo(() => repositories.filter((item) => `${item.name} ${item.description}`.toLowerCase().includes(search.toLowerCase())), [repositories, search]);

  let content: React.ReactNode;
  if (section === "overview") content = <Dashboard data={dashboard} t={t} />;
  else if (section === "repositories") content = <Panel title={t("osRepositories.repositories")} actions={canManage && <button className="button-primary" onClick={() => setRepositoryDialog(null)}><Plus />{t("osRepositories.addRepository")}</button>}><Search value={search} onChange={setSearch} t={t} /><div className="osr-card-grid">{filteredRepositories.map((item) => <RepositoryCard key={item.id} item={item} canManage={canManage} canSync={canSync} t={t} onEdit={() => setRepositoryDialog(item)} onFilter={() => setFilterRepository(item)} onSync={() => void sync(item)} />)}</div>{!filteredRepositories.length && <Empty t={t} />}</Panel>;
  else if (section === "packages") content = <Panel title={t("osRepositories.packages")} actions={permissions.includes("os-repositories.packages.upload") && <button className="button-primary" onClick={() => setUploadOpen(true)}><Upload />{t("osRepositories.upload")}</button>}><Search value={search} onChange={setSearch} t={t} /><Table heads={[t("common.name"), t("osRepositories.version"), t("osRepositories.architecture"), t("osRepositories.repository"), t("osRepositories.size"), t("common.status"), t("column.actions")]} rows={packages.map((item) => [<button className="osr-link-button" onClick={() => setPackageOpen(item)}><strong>{item.name}</strong></button>, `${item.epoch ? `${item.epoch}:` : ""}${item.version}${item.release ? `-${item.release}` : ""}`, item.architecture, repositories.find((repo) => repo.id === item.repository_id)?.name || item.repository_id.slice(0, 8), bytes(item.size_bytes), item.signature_status, <button title={t("action.details")} onClick={() => setPackageOpen(item)}><Eye /></button>])} /></Panel>;
  else if (section === "synchronizations" || section === "jobs") content = <Jobs jobs={jobs} t={t} canCancel={permissions.includes("os-repositories.jobs.cancel")} onRefresh={refresh} onOpen={setJobOpen} />;
  else if (section === "snapshots") content = <Panel title={t("osRepositories.snapshots")} actions={permissions.includes("os-repositories.snapshots.manage") && <button className="button-primary" onClick={() => setSnapshotOpen(true)}><Plus />{t("osRepositories.createSnapshot")}</button>}><Table heads={[t("common.name"), t("osRepositories.repository"), t("osRepositories.packages"), t("osRepositories.size"), t("osRepositories.created")]} rows={snapshots.map((item) => [item.name, repositories.find((repo) => repo.id === item.repository_id)?.name || "—", item.package_count, bytes(item.logical_size), new Date(item.created_at * 1000).toLocaleString()])} /></Panel>;
  else if (section === "channels") content = <Channels channels={channels} snapshots={snapshots} permissions={permissions} t={t} onRefresh={refresh} />;
  else if (section === "builder") content = <Panel title={t("osRepositories.builder")} actions={permissions.includes("os-repositories.packages.build") && <button className="button-primary" onClick={() => setBuildOpen(true)}><PackageOpen />{t("osRepositories.buildPackage")}</button>}><p className="osr-hint">{t("osRepositories.builderHint")}</p></Panel>;
  else if (section === "keys") content = <Panel title={t("osRepositories.keys")} actions={permissions.includes("os-repositories.keys.manage") && <button className="button-primary" onClick={() => setKeyOpen(true)}><Plus />{t("osRepositories.addKey")}</button>}><Table heads={[t("common.name"), t("osRepositories.fingerprint"), t("common.status"), t("osRepositories.privateKey"), t("column.actions")]} rows={keys.map((item) => [item.name, <code>{item.fingerprint}</code>, item.status, item.secret_configured ? t("common.yes") : t("common.no"), permissions.includes("os-repositories.keys.manage") ? <button className="danger" title={t("action.delete")} onClick={() => void api.deleteOsRepositoryKey(item.id).then(refresh)}><Trash2 /></button> : ""]) } /></Panel>;
  else if (section === "assignments") content = <Panel title={t("osRepositories.assignments")} actions={permissions.includes("os-repositories.hosts.assign") && <button className="button-primary" onClick={() => setAssignmentOpen(true)}><Plus />{t("osRepositories.addAssignment")}</button>}><Table heads={[t("osRepositories.repository"), t("osRepositories.channel"), t("osRepositories.target"), t("osRepositories.distribution"), t("column.actions")]} rows={assignments.map((item) => [item.repository_name, item.channel, item.host_id || item.group_id || "—", `${item.distribution} ${item.distribution_version}`, <div className="module-row-actions"><button title={t("osRepositories.configuration")} onClick={() => void api.osRepositoryAssignmentConfiguration(item.id).then(setConfiguration)}><FileText /></button>{permissions.includes("os-repositories.hosts.assign") && <button className="danger" title={t("action.delete")} onClick={() => void api.deleteOsRepositoryAssignment(item.id).then(refresh)}><Trash2 /></button>}</div>])} /></Panel>;
  else if (section === "history") content = <Panel title={t("module.section.history")}><Table heads={[t("osRepositories.created"), t("osRepositories.actor"), t("osRepositories.action"), t("osRepositories.target")]} rows={history.map((item) => [new Date(item.created_at * 1000).toLocaleString(), item.actor, item.action, item.target])} /></Panel>;
  else content = <Settings value={settings} canSave={permissions.includes("os-repositories.configure")} t={t} toast={toast} onSaved={refresh} />;

  return <><ModuleAppShell className="os-repositories-app" name={t("osRepositories.name")} status={status} activeJob={activeJob ? { operation: activeJob.operation, progress: activeJob.progress } : null} section={section} sections={visibleSections} t={t} onSection={setSection} actions={<button onClick={() => void refresh()} disabled={loading}><RefreshCw className={loading ? "spin" : ""} />{t("action.refresh")}</button>}>{loading && !dashboard ? <div className="module-loading"><RefreshCw className="spin" />{t("common.loading")}</div> : content}</ModuleAppShell>{repositoryDialog !== undefined && <RepositoryDialog value={repositoryDialog} t={t} toast={toast} onClose={() => setRepositoryDialog(undefined)} onSaved={refresh} />}{filterRepository && <FilterDialog repository={filterRepository} t={t} toast={toast} onClose={() => setFilterRepository(null)} />}{buildOpen && <BuildDialog repositories={repositories} t={t} toast={toast} onClose={() => setBuildOpen(false)} onSaved={refresh} />}{uploadOpen && <UploadDialog repositories={repositories} t={t} toast={toast} onClose={() => setUploadOpen(false)} onSaved={refresh} />}{snapshotOpen && <SnapshotDialog repositories={repositories} t={t} toast={toast} onClose={() => setSnapshotOpen(false)} onSaved={refresh} />}{keyOpen && <KeyDialog t={t} toast={toast} onClose={() => setKeyOpen(false)} onSaved={refresh} />}{assignmentOpen && <AssignmentDialog repositories={repositories} t={t} toast={toast} onClose={() => setAssignmentOpen(false)} onSaved={refresh} />}{jobOpen && <JobDialog id={jobOpen} t={t} onClose={() => setJobOpen(null)} />}{packageOpen && <PackageDialog item={packageOpen} t={t} onClose={() => setPackageOpen(null)} />}{configuration && <TextPreview title={t("osRepositories.configuration")} filename={configuration.filename} content={configuration.content} t={t} onClose={() => setConfiguration(null)} />}</>;
}

function Dashboard({ data, t }: { data: OsRepositoryDashboard | null; t: Translate }) {
  const cards = data ? [["repositories", data.repositories], ["packages", data.packages], ["snapshots", data.snapshots], ["published", data.published_channels], ["hosts", data.hosts], ["space", bytes(data.size_bytes)], ["pending", data.pending_packages], ["errors", data.errors]] : [];
  return <><div className="osr-stat-grid">{cards.map(([key, value]) => <article key={key}><span>{t(`osRepositories.dashboard.${key}`)}</span><strong>{value}</strong></article>)}</div>{data?.errors ? <div className="osr-alert"><CircleAlert />{t("osRepositories.dashboard.errorsHint")}</div> : null}</>;
}
function Panel({ title, actions, children }: { title: string; actions?: React.ReactNode; children: React.ReactNode }) { return <section className="osr-panel"><header><h3>{title}</h3><div>{actions}</div></header>{children}</section>; }
function Search({ value, onChange, t }: { value: string; onChange: (value: string) => void; t: Translate }) { return <label className="osr-search"><span>{t("action.search")}</span><input value={value} placeholder={t("osRepositories.search")} onChange={(event) => onChange(event.target.value)} /></label>; }
function Empty({ t }: { t: Translate }) { return <div className="empty-state"><Archive /><strong>{t("osRepositories.empty")}</strong></div>; }
function Table({ heads, rows }: { heads: string[]; rows: React.ReactNode[][] }) { return <div className="module-table-wrap"><table className="module-table"><thead><tr>{heads.map((head) => <th key={head}>{head}</th>)}</tr></thead><tbody>{rows.map((row, index) => <tr key={index}>{row.map((cell, cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>)}</tbody></table>{!rows.length && <div className="empty-state">—</div>}</div>; }
function RepositoryCard({ item, canManage, canSync, t, onEdit, onFilter, onSync }: { item: OsRepository; canManage: boolean; canSync: boolean; t: Translate; onEdit: () => void; onFilter: () => void; onSync: () => void }) { return <article className="osr-repository-card"><header><PackageOpen /><div><strong>{item.name}</strong><small>{item.format.toUpperCase()} · {item.kind}{item.auth_type !== "none" ? ` · ${item.auth_type}` : ""}</small></div><span className={`status-badge ${item.last_sync_status === "failed" ? "error" : "ok"}`}>{item.active ? t("common.enabled") : t("common.disabled")}</span></header><p>{item.description || "—"}</p><dl><div><dt>{t("osRepositories.distribution")}</dt><dd>{item.distribution} {item.distribution_version}</dd></div><div><dt>{t("osRepositories.packages")}</dt><dd>{item.package_count}</dd></div><div><dt>{t("osRepositories.size")}</dt><dd>{bytes(item.size_bytes)}</dd></div><div><dt>{t("osRepositories.architecture")}</dt><dd>{item.architectures.join(", ")}</dd></div></dl>{(canManage || canSync) && <footer>{canManage && <><button onClick={onEdit}>{t("action.edit")}</button><button onClick={onFilter}><ListFilter />{t("osRepositories.filters")}</button></>}{canSync && <button onClick={onSync}><RotateCcw />{t("osRepositories.sync")}</button>}</footer>}</article>; }
function Jobs({ jobs, t, canCancel, onRefresh, onOpen }: { jobs: OsRepositoryJob[]; t: Translate; canCancel: boolean; onRefresh: () => Promise<void>; onOpen: (id: string) => void }) { return <Panel title={t("osRepositories.jobs")}><Table heads={[t("osRepositories.created"), t("common.status"), t("osRepositories.stage"), t("osRepositories.progress"), t("column.actions")]} rows={jobs.map((job) => [new Date(job.created_at * 1000).toLocaleString(), job.status, job.stage, `${job.progress}%`, <div className="module-row-actions"><button onClick={() => onOpen(job.id)}>{t("action.details")}</button>{canCancel && ["queued", "running"].includes(job.status) && <button onClick={() => void api.cancelOsRepositoryJob(job.id).then(onRefresh)}>{t("action.cancel")}</button>}{["failed", "cancelled"].includes(job.status) && <button onClick={() => void api.retryOsRepositoryJob(job.id).then(onRefresh)}>{t("action.retry")}</button>}</div>])} /></Panel>; }
function Channels({ channels, snapshots, permissions, t, onRefresh }: { channels: OsRepositoryChannel[]; snapshots: OsRepositorySnapshot[]; permissions: string[]; t: Translate; onRefresh: () => Promise<void> }) {
  const [selected, setSelected] = useState<Record<string, string>>({});
  const [pending, setPending] = useState<{ channel: OsRepositoryChannel; snapshotId: string; plan: Record<string, unknown> } | null>(null);
  async function prepare(channel: OsRepositoryChannel) { const snapshotId = selected[channel.id]; if (!snapshotId) return; const plan = await api.osRepositoryChannelPlan(channel.id, snapshotId); setPending({ channel, snapshotId, plan }); }
  async function publish() { if (!pending) return; await api.promoteOsRepositoryChannel(pending.channel.id, pending.snapshotId, pending.channel.name === "production"); setPending(null); await onRefresh(); }
  return <><Panel title={t("osRepositories.channels")}><div className="osr-channel-grid">{channels.map((channel) => <article key={channel.id}><header><Shield channel={channel.name} /><div><strong>{channel.repository_name}</strong><span>{channel.name}</span></div></header><select aria-label={`${channel.repository_name} ${channel.name}`} value={selected[channel.id] || channel.snapshot_id || ""} onChange={(event) => setSelected((current) => ({ ...current, [channel.id]: event.target.value }))}><option value="">{t("osRepositories.selectSnapshot")}</option>{snapshots.filter((item) => item.repository_id === channel.repository_id).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><div className="module-row-actions">{permissions.includes(channel.name === "production" ? "os-repositories.channels.promote" : "os-repositories.snapshots.manage") && <button className="button-primary" disabled={!selected[channel.id]} onClick={() => void prepare(channel)}>{t("osRepositories.publish")}</button>}{channel.previous_snapshot_id && permissions.includes(channel.name === "production" ? "os-repositories.channels.promote" : "os-repositories.snapshots.manage") && <button onClick={() => void api.rollbackOsRepositoryChannel(channel.id, channel.name === "production").then(onRefresh)}><RotateCcw />{t("osRepositories.rollback")}</button>}</div></article>)}</div></Panel>{pending && <Modal title={t("osRepositories.publishPlan")} closeLabel={t("action.close")} onClose={() => setPending(null)} footer={<><button onClick={() => setPending(null)}>{t("action.cancel")}</button><button className="button-primary" onClick={() => void publish()}>{t("action.confirm")}</button></>}><p>{t("osRepositories.publishWarning")}</p><pre className="osr-code-preview">{JSON.stringify(pending.plan, null, 2)}</pre></Modal>}</>;
}
function Shield({ channel }: { channel: string }) { return channel === "production" ? <KeyRound /> : <Archive />; }

function RepositoryDialog({ value, t, toast, onClose, onSaved }: { value: OsRepository | null; t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [form, setForm] = useState({ name: value?.name || "", description: value?.description || "", kind: value?.kind || "local", format: value?.format || "apt", distribution: value?.distribution || "ubuntu", distribution_version: value?.distribution_version || "24.04", architectures: value?.architectures.join(",") || "amd64", source_url: value?.source_url || "", active: value?.active ?? true, schedule: value?.schedule || "", retention_count: value?.retention_count || 10, signing_key_id: value?.signing_key_id || null, allow_private_network: value?.allow_private_network ?? false, allow_private_http: value?.allow_private_http ?? false, auth_type: value?.auth_type || "none", auth_username: value?.auth_username || "", auth_secret: "" });
  const [plan, setPlan] = useState<Record<string, unknown> | null>(null); const [busy, setBusy] = useState(false);
  const payload = () => ({ ...form, architectures: form.architectures.split(",").map((item) => item.trim()).filter(Boolean), source_url: form.kind === "local" ? "" : form.source_url, auth_type: form.kind === "local" ? "none" : form.auth_type, auth_username: form.kind === "local" || form.auth_type !== "basic" ? "" : form.auth_username, auth_secret: form.kind === "local" || form.auth_type === "none" ? "" : form.auth_secret });
  async function prepare(event: React.FormEvent) { event.preventDefault(); try { setPlan(await api.planOsRepository(payload(), value?.id)); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } }
  async function save() { if (busy) return; setBusy(true); try { await api.saveOsRepository(payload(), value?.id); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal wide title={t(value ? "osRepositories.editRepository" : "osRepositories.addRepository")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button>{plan ? <button type="button" className="button-primary" disabled={busy} onClick={() => void save()}>{t("action.confirm")}</button> : <button type="submit" form="osr-repository-form" className="button-primary">{t("osRepositories.showPlan")}</button>}</>}><form id="osr-repository-form" className="module-form-grid" onSubmit={prepare}><label>{t("common.name")}<input required value={form.name} onChange={(e) => { setPlan(null); setForm({ ...form, name: e.target.value }); }} /></label><label>{t("osRepositories.kind")}<select value={form.kind} onChange={(e) => { setPlan(null); setForm({ ...form, kind: e.target.value as "local" | "mirror" }); }}><option value="local">local</option><option value="mirror">mirror</option></select></label><label>{t("osRepositories.format")}<select value={form.format} onChange={(e) => { setPlan(null); setForm({ ...form, format: e.target.value as "apt" | "rpm" }); }}><option value="apt">APT</option><option value="rpm">RPM</option></select></label><label>{t("osRepositories.distribution")}<input required value={form.distribution} onChange={(e) => { setPlan(null); setForm({ ...form, distribution: e.target.value }); }} /></label><label>{t("osRepositories.distributionVersion")}<input required value={form.distribution_version} onChange={(e) => { setPlan(null); setForm({ ...form, distribution_version: e.target.value }); }} /></label><label>{t("osRepositories.architectures")}<input required value={form.architectures} onChange={(e) => { setPlan(null); setForm({ ...form, architectures: e.target.value }); }} /></label><label>{t("osRepositories.schedule")}<input value={form.schedule} placeholder="0 2 * * *" onChange={(e) => { setPlan(null); setForm({ ...form, schedule: e.target.value }); }} /></label><label>{t("osRepositories.retention")}<input min="1" max="1000" type="number" value={form.retention_count} onChange={(e) => { setPlan(null); setForm({ ...form, retention_count: Number(e.target.value) }); }} /></label>{form.kind === "mirror" && <><label className="wide">{t("osRepositories.sourceUrl")}<input type="url" required value={form.source_url} onChange={(e) => { setPlan(null); setForm({ ...form, source_url: e.target.value }); }} /></label><label>{t("osRepositories.authType")}<select value={form.auth_type} onChange={(e) => { setPlan(null); setForm({ ...form, auth_type: e.target.value as "none" | "bearer" | "basic" }); }}><option value="none">{t("osRepositories.authNone")}</option><option value="bearer">Bearer token</option><option value="basic">HTTP Basic</option></select></label>{form.auth_type === "basic" && <label>{t("osRepositories.authUsername")}<input required autoComplete="username" value={form.auth_username} onChange={(e) => { setPlan(null); setForm({ ...form, auth_username: e.target.value }); }} /></label>}{form.auth_type !== "none" && <label className={form.auth_type === "bearer" ? "wide" : undefined}>{t("osRepositories.authSecret")}<input type="password" required={!value?.auth_secret_configured} autoComplete="new-password" value={form.auth_secret} placeholder={value?.auth_secret_configured ? t("osRepositories.authSecretConfigured") : ""} onChange={(e) => { setPlan(null); setForm({ ...form, auth_secret: e.target.value }); }} /></label>}<label className="checkbox-row"><input type="checkbox" checked={form.allow_private_network} onChange={(e) => { setPlan(null); setForm({ ...form, allow_private_network: e.target.checked }); }} />{t("osRepositories.allowPrivate")}</label><label className="checkbox-row"><input type="checkbox" checked={form.allow_private_http} onChange={(e) => { setPlan(null); setForm({ ...form, allow_private_http: e.target.checked }); }} />{t("osRepositories.allowHttp")}</label>{value?.auth_secret_configured && form.auth_type !== "none" && <p className="osr-hint wide">{t("osRepositories.authSecretHint")}</p>}</>}<label className="wide">{t("osRepositories.description")}<textarea value={form.description} onChange={(e) => { setPlan(null); setForm({ ...form, description: e.target.value }); }} /></label>{plan && <pre className="osr-code-preview wide">{JSON.stringify(plan, null, 2)}</pre>}</form></Modal>;
}

type RepositoryFilterForm = {
  name: string; include_names: string; exclude_names: string; include_globs: string; exclude_globs: string;
  include_regex: string; exclude_regex: string; architectures: string; minimum_version: string; maximum_version: string;
  latest_versions: string; maximum_size_mb: string; exclude_source: boolean; exclude_debug: boolean; exclude_devel: boolean;
};

const emptyRepositoryFilter: RepositoryFilterForm = {
  name: "default", include_names: "", exclude_names: "", include_globs: "", exclude_globs: "", include_regex: "", exclude_regex: "",
  architectures: "", minimum_version: "", maximum_version: "", latest_versions: "", maximum_size_mb: "", exclude_source: true, exclude_debug: false, exclude_devel: false,
};

function filterList(value: string): string[] { return value.split(/[\n,]/).map((item) => item.trim()).filter(Boolean); }
function filterListText(value: unknown): string { return Array.isArray(value) ? value.join(", ") : ""; }

function FilterDialog({ repository, t, toast, onClose }: { repository: OsRepository; t: Translate; toast: ToastFn; onClose: () => void }) {
  const [form, setForm] = useState<RepositoryFilterForm>(emptyRepositoryFilter);
  const [preview, setPreview] = useState<Record<string, unknown> | null>(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let active = true;
    void api.osRepository(repository.id).then((details) => {
      const saved = details.filters.find((item) => item.active);
      if (!active || !saved) return;
      const rules = saved.rules;
      setForm({
        name: String(rules.name || saved.name || "default"), include_names: filterListText(rules.include_names), exclude_names: filterListText(rules.exclude_names),
        include_globs: filterListText(rules.include_globs), exclude_globs: filterListText(rules.exclude_globs), include_regex: String(rules.include_regex || ""),
        exclude_regex: String(rules.exclude_regex || ""), architectures: filterListText(rules.architectures), minimum_version: String(rules.minimum_version || ""),
        maximum_version: String(rules.maximum_version || ""), latest_versions: rules.latest_versions ? String(rules.latest_versions) : "",
        maximum_size_mb: rules.maximum_size ? String(Math.ceil(Number(rules.maximum_size) / 1024 ** 2)) : "", exclude_source: rules.exclude_source !== false,
        exclude_debug: Boolean(rules.exclude_debug), exclude_devel: Boolean(rules.exclude_devel),
      });
    }).catch((error) => toast(error instanceof Error ? error.message : t("error.generic"), "error"));
    return () => { active = false; };
  }, [repository.id, t, toast]);
  const payload = () => ({
    name: form.name, include_names: filterList(form.include_names), exclude_names: filterList(form.exclude_names), include_globs: filterList(form.include_globs),
    exclude_globs: filterList(form.exclude_globs), include_regex: form.include_regex, exclude_regex: form.exclude_regex, architectures: filterList(form.architectures),
    minimum_version: form.minimum_version, maximum_version: form.maximum_version, latest_versions: form.latest_versions ? Number(form.latest_versions) : null,
    maximum_size: form.maximum_size_mb ? Number(form.maximum_size_mb) * 1024 ** 2 : null, exclude_source: form.exclude_source, exclude_debug: form.exclude_debug,
    exclude_devel: form.exclude_devel, minimum_published_at: null, maximum_published_at: null,
  });
  async function prepare(event: React.FormEvent) { event.preventDefault(); try { setPreview(await api.previewOsRepositoryFilter(repository.id, payload())); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } }
  async function save() { if (busy) return; setBusy(true); try { await api.saveOsRepositoryFilter(repository.id, payload()); toast(t("osRepositories.filterSaved"), "ok"); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal wide title={`${t("osRepositories.filters")}: ${repository.name}`} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button form="osr-filter-form" type="submit">{t("osRepositories.filterPreview")}</button><button type="button" className="button-primary" disabled={!preview || busy} onClick={() => void save()}>{t("osRepositories.saveFilter")}</button></>}><form id="osr-filter-form" className="module-form-grid" onSubmit={prepare}><p className="osr-hint wide">{t("osRepositories.filterSnapshotHint")}</p><label>{t("osRepositories.filterName")}<input required value={form.name} onChange={(e) => { setPreview(null); setForm({ ...form, name: e.target.value }); }} /></label><label>{t("osRepositories.filterArchitectures")}<input value={form.architectures} placeholder="amd64, arm64" onChange={(e) => { setPreview(null); setForm({ ...form, architectures: e.target.value }); }} /></label><label className="wide">{t("osRepositories.includeNames")}<textarea rows={2} value={form.include_names} onChange={(e) => { setPreview(null); setForm({ ...form, include_names: e.target.value }); }} /></label><label className="wide">{t("osRepositories.excludeNames")}<textarea rows={2} value={form.exclude_names} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_names: e.target.value }); }} /></label><label>{t("osRepositories.includeGlobs")}<input placeholder="webnas-*, nginx*" value={form.include_globs} onChange={(e) => { setPreview(null); setForm({ ...form, include_globs: e.target.value }); }} /></label><label>{t("osRepositories.excludeGlobs")}<input placeholder="*-beta, *-test" value={form.exclude_globs} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_globs: e.target.value }); }} /></label><label>{t("osRepositories.includeRegex")}<input value={form.include_regex} onChange={(e) => { setPreview(null); setForm({ ...form, include_regex: e.target.value }); }} /></label><label>{t("osRepositories.excludeRegex")}<input value={form.exclude_regex} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_regex: e.target.value }); }} /></label><label>{t("osRepositories.minimumVersion")}<input value={form.minimum_version} onChange={(e) => { setPreview(null); setForm({ ...form, minimum_version: e.target.value }); }} /></label><label>{t("osRepositories.maximumVersion")}<input value={form.maximum_version} onChange={(e) => { setPreview(null); setForm({ ...form, maximum_version: e.target.value }); }} /></label><label>{t("osRepositories.latestVersions")}<input type="number" min="1" max="100" value={form.latest_versions} onChange={(e) => { setPreview(null); setForm({ ...form, latest_versions: e.target.value }); }} /></label><label>{t("osRepositories.maximumSizeMb")}<input type="number" min="1" max="20480" value={form.maximum_size_mb} onChange={(e) => { setPreview(null); setForm({ ...form, maximum_size_mb: e.target.value }); }} /></label><label className="checkbox-row"><input type="checkbox" checked={form.exclude_source} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_source: e.target.checked }); }} />{t("osRepositories.excludeSource")}</label><label className="checkbox-row"><input type="checkbox" checked={form.exclude_debug} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_debug: e.target.checked }); }} />{t("osRepositories.excludeDebug")}</label><label className="checkbox-row"><input type="checkbox" checked={form.exclude_devel} onChange={(e) => { setPreview(null); setForm({ ...form, exclude_devel: e.target.checked }); }} />{t("osRepositories.excludeDevel")}</label>{preview && <div className="osr-stat-grid wide"><article><span>{t("osRepositories.includedPackages")}</span><strong>{String(preview.included ?? 0)}</strong></article><article><span>{t("osRepositories.rejectedPackages")}</span><strong>{String(preview.rejected ?? 0)}</strong></article><article><span>{t("osRepositories.estimatedSize")}</span><strong>{bytes(Number(preview.estimated_size || 0))}</strong></article></div>}</form></Modal>;
}

function BuildDialog({ repositories, t, toast, onClose, onSaved }: { repositories: OsRepository[]; t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [repositoryId, setRepositoryId] = useState(repositories[0]?.id || ""); const repository = repositories.find((item) => item.id === repositoryId);
  const [form, setForm] = useState({ name: "", version: "1.0.0", release: "1", architecture: "all", description: "", maintainer: "WebNAS", vendor: "WebNAS", license: "Proprietary", homepage: "", dependencies: "", conflicts: "", targetPath: "/usr/share/webnas/package-file", mode: "0644", configFile: false, scripts: false, postInstall: "" });
  const [file, setFile] = useState<{ name: string; content_base64: string } | null>(null); const [busy, setBusy] = useState(false);
  useEffect(() => setForm((current) => ({ ...current, architecture: repository?.format === "rpm" ? "noarch" : "all" })), [repository?.format]);
  async function readFile(value: File | undefined) { if (!value) { setFile(null); return; } const buffer = await value.arrayBuffer(); const bytes = new Uint8Array(buffer); let binary = ""; for (let offset = 0; offset < bytes.length; offset += 0x8000) binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000)); setFile({ name: value.name, content_base64: btoa(binary) }); }
  async function save(event: React.FormEvent) { event.preventDefault(); if (busy) return; setBusy(true); try { await api.buildOsRepositoryPackage({ repository_id: repositoryId, format: repository?.format || "apt", name: form.name, version: form.version, release: form.release, architecture: form.architecture, description: form.description, maintainer: form.maintainer, vendor: form.vendor, license: form.license, homepage: form.homepage, dependencies: form.dependencies.split(",").map((item) => item.trim()).filter(Boolean), conflicts: form.conflicts.split(",").map((item) => item.trim()).filter(Boolean), files: file ? [{ source_name: file.name, target_path: form.targetPath, owner: "root", group: "root", mode: form.mode, config_file: form.configFile, content_base64: file.content_base64 }] : [], maintainer_scripts: form.scripts && form.postInstall ? { post_install: form.postInstall } : {}, allow_maintainer_scripts: form.scripts }); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal wide title={t("osRepositories.buildPackage")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button type="submit" form="osr-build-form" className="button-primary" disabled={busy}>{t("osRepositories.build")}</button></>}><form id="osr-build-form" className="module-form-grid" onSubmit={save}><label className="wide">{t("osRepositories.repository")}<select value={repositoryId} onChange={(e) => setRepositoryId(e.target.value)}>{repositories.map((item) => <option key={item.id} value={item.id}>{item.name} ({item.format.toUpperCase()})</option>)}</select></label><label>{t("common.name")}<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label><label>{t("osRepositories.version")}<input required value={form.version} onChange={(e) => setForm({ ...form, version: e.target.value })} /></label><label>{t("osRepositories.release")}<input required value={form.release} onChange={(e) => setForm({ ...form, release: e.target.value })} /></label><label>{t("osRepositories.architecture")}<input required value={form.architecture} onChange={(e) => setForm({ ...form, architecture: e.target.value })} /></label><label className="wide">{t("osRepositories.description")}<textarea required value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} /></label><label>{t("osRepositories.maintainer")}<input value={form.maintainer} onChange={(e) => setForm({ ...form, maintainer: e.target.value })} /></label><label>{t("osRepositories.vendor")}<input value={form.vendor} onChange={(e) => setForm({ ...form, vendor: e.target.value })} /></label><label>{t("osRepositories.license")}<input value={form.license} onChange={(e) => setForm({ ...form, license: e.target.value })} /></label><label>{t("osRepositories.homepage")}<input type="url" value={form.homepage} onChange={(e) => setForm({ ...form, homepage: e.target.value })} /></label><label>{t("osRepositories.dependencies")}<input value={form.dependencies} onChange={(e) => setForm({ ...form, dependencies: e.target.value })} /></label><label>{t("osRepositories.conflicts")}<input value={form.conflicts} onChange={(e) => setForm({ ...form, conflicts: e.target.value })} /></label><label className="wide">{t("osRepositories.sourceFile")}<input type="file" onChange={(e) => void readFile(e.target.files?.[0])} /></label>{file && <><label className="wide">{t("osRepositories.targetPath")}<input required value={form.targetPath} onChange={(e) => setForm({ ...form, targetPath: e.target.value })} /></label><label>{t("osRepositories.fileMode")}<input required value={form.mode} onChange={(e) => setForm({ ...form, mode: e.target.value })} /></label><label className="checkbox-row"><input type="checkbox" checked={form.configFile} onChange={(e) => setForm({ ...form, configFile: e.target.checked })} />{t("osRepositories.configFile")}</label></>}<label className="checkbox-row wide"><input type="checkbox" checked={form.scripts} onChange={(e) => setForm({ ...form, scripts: e.target.checked })} />{t("osRepositories.enableScripts")}</label>{form.scripts && <><label className="wide">{t("osRepositories.postInstall")}<textarea value={form.postInstall} onChange={(e) => setForm({ ...form, postInstall: e.target.value })} /></label><div className="osr-alert wide"><CircleAlert />{t("osRepositories.scriptWarning")}</div></>}</form></Modal>;
}
function Settings({ value, canSave, t, toast, onSaved }: { value: { listen_address: string; port: number; public_base_url: string; upload_limit_mb: number; max_parallel_syncs: number }; canSave: boolean; t: Translate; toast: ToastFn; onSaved: () => Promise<void> }) { const [form, setForm] = useState(value); useEffect(() => setForm(value), [value]); return <Panel title={t("module.section.settings")}><form className="module-form-grid" onSubmit={(event) => { event.preventDefault(); void api.saveOsRepositorySettings(form).then(onSaved).catch((error) => toast(error instanceof Error ? error.message : t("error.generic"), "error")); }}><label>{t("osRepositories.listenAddress")}<input value={form.listen_address} onChange={(e) => setForm({ ...form, listen_address: e.target.value })} /></label><label>{t("osRepositories.port")}<input type="number" value={form.port} onChange={(e) => setForm({ ...form, port: Number(e.target.value) })} /></label><label className="wide">{t("osRepositories.publicUrl")}<input type="url" value={form.public_base_url} onChange={(e) => setForm({ ...form, public_base_url: e.target.value })} /></label><label>{t("osRepositories.uploadLimit")}<input type="number" value={form.upload_limit_mb} onChange={(e) => setForm({ ...form, upload_limit_mb: Number(e.target.value) })} /></label>{canSave && <button className="button-primary" type="submit">{t("action.save")}</button>}</form></Panel>; }

function UploadDialog({ repositories, t, toast, onClose, onSaved }: { repositories: OsRepository[]; t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [repositoryId, setRepositoryId] = useState(repositories[0]?.id || ""); const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!file || busy) return; setBusy(true); try { await api.uploadOsRepositoryPackage(repositoryId, file); toast(t("osRepositories.packageUploaded"), "ok"); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal title={t("osRepositories.upload")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button form="osr-upload" type="submit" className="button-primary" disabled={!file || busy}>{busy ? t("common.loading") : t("osRepositories.upload")}</button></>}><form id="osr-upload" className="module-form-grid" onSubmit={submit}><label className="wide">{t("osRepositories.repository")}<select required value={repositoryId} onChange={(e) => setRepositoryId(e.target.value)}>{repositories.map((item) => <option key={item.id} value={item.id}>{item.name} ({item.format.toUpperCase()})</option>)}</select></label><label className="wide">{t("osRepositories.packageFile")}<input required type="file" accept=".deb,.rpm" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><p className="osr-hint wide">{t("osRepositories.uploadHint")}</p></form></Modal>;
}

function SnapshotDialog({ repositories, t, toast, onClose, onSaved }: { repositories: OsRepository[]; t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [repositoryId, setRepositoryId] = useState(repositories[0]?.id || ""); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (busy) return; setBusy(true); try { await api.createOsRepositorySnapshot(repositoryId, name, description); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal title={t("osRepositories.createSnapshot")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button form="osr-snapshot" type="submit" className="button-primary" disabled={!repositoryId || busy}>{t("action.create")}</button></>}><form id="osr-snapshot" className="module-form-grid" onSubmit={submit}><label className="wide">{t("osRepositories.repository")}<select required value={repositoryId} onChange={(e) => setRepositoryId(e.target.value)}>{repositories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="wide">{t("common.name")}<input value={name} placeholder={t("osRepositories.automaticName")} onChange={(e) => setName(e.target.value)} /></label><label className="wide">{t("osRepositories.description")}<textarea value={description} onChange={(e) => setDescription(e.target.value)} /></label></form></Modal>;
}

function KeyDialog({ t, toast, onClose, onSaved }: { t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [mode, setMode] = useState<"import" | "generate">("import"); const [form, setForm] = useState({ name: "", identity: "", expires: "2y", fingerprint: "", public_key: "", private_key: "", passphrase: "" }); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (busy) return; setBusy(true); try { if (mode === "generate") await api.generateOsRepositoryKey({ name: form.name, identity: form.identity, expires: form.expires, passphrase: form.passphrase }); else await api.saveOsRepositoryKey({ name: form.name, fingerprint: form.fingerprint, public_key: form.public_key, private_key: form.private_key, passphrase: form.passphrase }); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  return <Modal wide title={t("osRepositories.addKey")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button form="osr-key" type="submit" className="button-primary" disabled={busy}>{t("action.save")}</button></>}><div className="osr-segmented"><button type="button" className={mode === "import" ? "active" : ""} onClick={() => setMode("import")}>{t("osRepositories.importKey")}</button><button type="button" className={mode === "generate" ? "active" : ""} onClick={() => setMode("generate")}>{t("osRepositories.generateKey")}</button></div><form id="osr-key" className="module-form-grid" onSubmit={submit}><label className="wide">{t("common.name")}<input required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></label>{mode === "generate" ? <><label>{t("osRepositories.identity")}<input required value={form.identity} onChange={(e) => setForm({ ...form, identity: e.target.value })} /></label><label>{t("osRepositories.expires")}<input required value={form.expires} onChange={(e) => setForm({ ...form, expires: e.target.value })} /></label></> : <><label className="wide">{t("osRepositories.fingerprint")}<input required value={form.fingerprint} onChange={(e) => setForm({ ...form, fingerprint: e.target.value })} /></label><label className="wide">{t("osRepositories.publicKey")}<textarea required rows={6} value={form.public_key} onChange={(e) => setForm({ ...form, public_key: e.target.value })} /></label><label className="wide">{t("osRepositories.privateKeyOptional")}<textarea rows={6} value={form.private_key} onChange={(e) => setForm({ ...form, private_key: e.target.value })} /></label></>}<label className="wide">{t("osRepositories.passphrase")}<input type="password" autoComplete="new-password" value={form.passphrase} onChange={(e) => setForm({ ...form, passphrase: e.target.value })} /></label><div className="osr-alert wide"><CircleAlert />{t("osRepositories.keyWarning")}</div></form></Modal>;
}

function AssignmentDialog({ repositories, t, toast, onClose, onSaved }: { repositories: OsRepository[]; t: Translate; toast: ToastFn; onClose: () => void; onSaved: () => Promise<void> }) {
  const [hosts, setHosts] = useState<HostsManagerHost[]>([]); const [groups, setGroups] = useState<HostsManagerGroup[]>([]); const [targetType, setTargetType] = useState<"host" | "group">("host"); const [repositoryId, setRepositoryId] = useState(repositories[0]?.id || ""); const [channel, setChannel] = useState("testing"); const [target, setTarget] = useState(""); const [busy, setBusy] = useState(false);
  useEffect(() => { void Promise.all([api.hostsManagerHosts(), api.hostsManagerGroups()]).then(([hostItems, groupItems]) => { setHosts(hostItems); setGroups(groupItems); }); }, []);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (busy) return; setBusy(true); try { await api.saveOsRepositoryAssignment({ repository_id: repositoryId, channel, host_id: targetType === "host" ? target : null, group_id: targetType === "group" ? target : null }); await onSaved(); onClose(); } catch (error) { toast(error instanceof Error ? error.message : t("error.generic"), "error"); } finally { setBusy(false); } }
  const targets = targetType === "host" ? hosts : groups;
  return <Modal title={t("osRepositories.addAssignment")} closeLabel={t("action.close")} onClose={onClose} footer={<><button onClick={onClose}>{t("action.cancel")}</button><button form="osr-assignment" type="submit" className="button-primary" disabled={!target || busy}>{t("action.save")}</button></>}><form id="osr-assignment" className="module-form-grid" onSubmit={submit}><label className="wide">{t("osRepositories.repository")}<select value={repositoryId} onChange={(e) => setRepositoryId(e.target.value)}>{repositories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>{t("osRepositories.channel")}<select value={channel} onChange={(e) => setChannel(e.target.value)}><option value="incoming">incoming</option><option value="testing">testing</option><option value="production">production</option><option value="archive">archive</option></select></label><label>{t("osRepositories.targetType")}<select value={targetType} onChange={(e) => { setTargetType(e.target.value as "host" | "group"); setTarget(""); }}><option value="host">{t("osRepositories.host")}</option><option value="group">{t("osRepositories.group")}</option></select></label><label className="wide">{t("osRepositories.target")}<select required value={target} onChange={(e) => setTarget(e.target.value)}><option value="">{t("osRepositories.selectTarget")}</option>{targets.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="osr-alert wide"><CircleAlert />{t("osRepositories.assignmentWarning")}</div></form></Modal>;
}

function JobDialog({ id, t, onClose }: { id: string; t: Translate; onClose: () => void }) {
  const [job, setJob] = useState<(OsRepositoryJob & { logs?: Array<{ id: number; stream: string; line: string }> }) | null>(null);
  useEffect(() => { let active = true; const load = () => api.osRepositoryJob(id).then((value) => { if (active) setJob(value); }); void load(); const polling = window.setInterval(() => void load(), 3000); let stream: EventSource | null = null; try { stream = new EventSource(`/api/modules/os-repositories/jobs/${encodeURIComponent(id)}/events`); stream.onmessage = (event) => { if (active) setJob(JSON.parse(event.data) as typeof job); }; } catch { /* polling remains active */ } return () => { active = false; window.clearInterval(polling); stream?.close(); }; }, [id]);
  return <Modal wide title={t("osRepositories.jobDetails")} closeLabel={t("action.close")} onClose={onClose} footer={<button onClick={onClose}>{t("action.close")}</button>}><div className="osr-job-summary"><strong>{job?.status || t("common.loading")}</strong><span>{job?.stage}</span><progress max="100" value={job?.progress || 0} /></div><pre className="osr-live-log" aria-live="polite">{job?.logs?.map((line) => `[${line.stream}] ${line.line}`).join("\n") || t("osRepositories.noLogs")}</pre></Modal>;
}

function PackageDialog({ item, t, onClose }: { item: OsRepositoryPackage; t: Translate; onClose: () => void }) { const details = [["version", `${item.epoch ? `${item.epoch}:` : ""}${item.version}-${item.release}`], ["architecture", item.architecture], ["distribution", item.distribution], ["size", bytes(item.size_bytes)], ["sha256", item.sha256], ["maintainer", item.maintainer], ["license", item.license], ["signature", item.signature_status], ["source", item.source]]; return <Modal wide title={item.name} closeLabel={t("action.close")} onClose={onClose} footer={<button onClick={onClose}>{t("action.close")}</button>}><dl className="osr-details-grid">{details.map(([key, value]) => <div key={key}><dt>{t(`osRepositories.${key}`)}</dt><dd>{value || "—"}</dd></div>)}</dl><h4>{t("osRepositories.description")}</h4><p>{item.description || "—"}</p><h4>{t("osRepositories.dependencies")}</h4><p>{item.dependencies.join(", ") || "—"}</p></Modal>; }

function TextPreview({ title, filename, content, t, onClose }: { title: string; filename: string; content: string; t: Translate; onClose: () => void }) { return <Modal wide title={title} closeLabel={t("action.close")} onClose={onClose} footer={<button onClick={onClose}>{t("action.close")}</button>}><p><strong>{filename}</strong></p><pre className="osr-code-preview">{content}</pre></Modal>; }
